'use strict'

// Thin redirect wrapper for smart routing
const upgradeTenant = require('../upgrade-tenant')

module.exports = Object.assign(upgrade, {
    _name: 'upgrade',
    options: [...(upgradeTenant.options || [])],
    flags: [...(upgradeTenant.flags || []), '--fix', '--report'],
    shortcuts: [...(upgradeTenant.shortcuts || [])],
    help: `
# SYNOPSIS

    *cds upgrade* [<tenant>] [options]

# DESCRIPTION

    Smart routing for upgrade commands:

    - *With tenant argument*: Routes to tenant upgrade (*cds upgrade-tenant*)
    - *Without tenant*: Routes to cds version upgrade

# TENANT UPGRADE

    *cds upgrade* <tenant> [options]

    DEPRECATION NOTICE: The tenant upgrade functionality has been renamed
    to *cds upgrade-tenant*. Using *cds upgrade* for tenant operations is
    deprecated and will be removed in a future version.

    Upgrade a tenant subscribed to a multitenant SaaS app.

    Options:
      -a, --at <url>           SaaS app URL
      -u, --user <credentials> Username and password for Basic Auth
      -l, --local              Run locally-installed @sap/cds-mtxs
      -b, --resolve-bindings   Resolve remote service bindings

# cds VERSION UPGRADE

    *cds upgrade* [--fix] [--report]

    Guided upgrade for CAP projects between major cds versions.

    The command:
      1. Detects project type and derives the target from the running cds-dk.
      2. Checks consistency of cds-related dependencies across the project.
      3. Proposes dependency updates and asks before applying them.
      4. Proposes removal of direct @sap/cds-compiler (and @sap/cds-dk in
         Node-only projects) declarations.
      5. Verifies resolved versions (npm ls / pom.xml).
      6. Offers to delete lock files and run npm install / mvn install.
      7. With --fix on Java projects, runs OpenRewrite over the source tree.
      8. Analyzes the project for required code changes. With --report,
         writes report.md and report.yaml at the project root.

    Flags:
      --fix                    Enable OpenRewrite pass for Java projects
      --report                 Write report.md and report.yaml to the project root

# SEE ALSO

    *cds upgrade-tenant* for tenant upgrade operations.

`})

async function upgrade(args, options = {}) {
    const hasTenantArg = args && args.length > 0 && args[0]

    if (hasTenantArg) {
        console.warn('\x1b[33m⚠ Deprecation Notice:\x1b[0m')
        console.warn('  The command \x1b[33mcds upgrade <tenant>\x1b[0m has been renamed to \x1b[32mcds upgrade-tenant <tenant>\x1b[0m')
        console.warn('  Please update your scripts to use \x1b[32mcds upgrade-tenant\x1b[0m instead.')
        console.warn('  This redirect will be removed in a future version.\n')
        return upgradeTenant(args, options)
    }

    const versionUpgrade = require('./upgrade')
    return versionUpgrade(options)
}
